"""Build a self-contained Russian rendering article. Python 3 + Pillow for captured PNGs."""
from pathlib import Path
import base64
import html
import io
import math
import re
from PIL import Image

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[1]
SECTIONS = []
TEAL, GOLD, BLUE, INK = '#087f8c', '#c27a27', '#6577c8', '#172b37'

def esc(s): return html.escape(str(s))
def section(id, title, subtitle, body):
    SECTIONS.append((id, title, subtitle, body))
def source(*paths):
    return '<div class="source"><span>В исходниках</span>' + ' · '.join(
        f'<a href="../../{p}">{esc(p)}</a>' for p in paths) + '</div>'
def note(title, body): return f'<aside class="note"><b>{title}</b><p>{body}</p></aside>'
def formula(s, desc): return f'<div class="formula"><div>{s}</div><p>{desc}</p></div>'
def figure(svg, caption):
    if re.match(r'^Схема \d+\.', caption):
        figure.number += 1
        caption = re.sub(r'^Схема \d+\.', f'Схема {figure.number}.', caption)
    return f'<figure class="diagram">{svg}<figcaption>{caption}</figcaption></figure>'
figure.number = 0
def svg(content, title, h=320, w=860):
    svg.count += 1
    marker = f'arr-{svg.count}'
    content=content.replace('url(#arr)', f'url(#{marker})')
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{esc(title)}"><title>{esc(title)}</title><defs><marker id="{marker}" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="{TEAL}"/></marker></defs>{content}</svg>'''
svg.count=0
def txt(x,y,s,size=16,fill=INK,anchor='start'):
    return f'<text x="{x}" y="{y}" fill="{fill}" font-size="{size}" text-anchor="{anchor}" font-family="Segoe UI,Arial,sans-serif">{esc(s)}</text>'
def rect(x,y,w,h,fill='#e5efed',stroke='none',rx=12):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{rx}" fill="{fill}" stroke="{stroke}"/>'
def line(x1,y1,x2,y2,color=TEAL,dash='',arrow=False,width=2):
    return f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" stroke="{color}" stroke-width="{width}" stroke-dasharray="{dash}"'+(' marker-end="url(#arr)"' if arrow else '')+'/>'
def box(x,y,w,title,sub='',fill='#e5efed'):
    return rect(x,y,w,68,fill)+txt(x+15,y+28,title,17)+txt(x+15,y+51,sub,12,'#52666e')
def circle(x,y,r,fill=TEAL): return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{fill}"/>'

def chart(title, series, xmin,xmax,ymin,ymax,xlabel,ylabel,xticks,yticks,h=340):
    x0,y0,ww,hh=72,48,748,h-114
    X=lambda x:x0+(x-xmin)/(xmax-xmin)*ww
    Y=lambda y:y0+hh-(y-ymin)/(ymax-ymin)*hh
    parts=[txt(x0,23,ylabel,13,'#52666e')]
    for v in yticks:
        parts += [line(x0,Y(v),x0+ww,Y(v),'#dbe2df',width=1),txt(x0-12,Y(v)+4,f'{v:g}',12,'#52666e','end')]
    for v in xticks:
        parts += [txt(X(v),y0+hh+25,f'{v:g}',12,'#52666e','middle')]
    parts += [txt(x0+ww,y0+hh+48,xlabel,13,'#52666e','end')]
    for name,color,pts in series:
        coords=' '.join(f'{X(x):.2f},{Y(max(ymin,min(ymax,y))):.2f}' for x,y in pts)
        parts += [f'<polyline points="{coords}" fill="none" stroke="{color}" stroke-width="3" stroke-linejoin="round"/>']
    out=svg(''.join(parts),title,h)
    out+='<div class="legend">'+''.join(f'<span><i style="background:{c}"></i>{n}</span>' for n,c,_ in series)+'</div>'
    return out

def photo(name, caption):
    p=HERE/'assets'/name
    if not p.exists(): return ''
    im=Image.open(p).convert('RGB'); out=io.BytesIO(); im.save(out,format='JPEG',quality=91,optimize=True)
    data=base64.b64encode(out.getvalue()).decode()
    return f'<figure class="photo"><img src="data:image/jpeg;base64,{data}" width="{im.width}" height="{im.height}" loading="lazy" alt="{esc(caption)}"><figcaption>{caption}</figcaption></figure>'

